effects.css:
[data-border-style="corner_brackets"]::after {
    border: none;
    background:
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 0 0 / 20px var(--sl-border-w) no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 0 0 / var(--sl-border-w) 20px no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 100% 0 / 20px var(--sl-border-w) no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 100% 0 / var(--sl-border-w) 20px no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 0 100% / 20px var(--sl-border-w) no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 0 100% / var(--sl-border-w) 20px no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 100% 100% / 20px var(--sl-border-w) no-repeat,
        linear-gradient(var(--sl-border-col), var(--sl-border-col)) 100% 100% / var(--sl-border-w) 20px no-repeat;
}

[data-border-style="cut_corners"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    clip-path: polygon(
        18px 0, calc(100% - 18px) 0,
        100% 18px, 100% calc(100% - 18px),
        calc(100% - 18px) 100%, 18px 100%,
        0 calc(100% - 18px), 0 18px
    );
}

@keyframes sl-np-pulse {
    0%, 100% { box-shadow: 0 0 5px var(--sl-border-col), inset 0 0 5px var(--sl-border-col); }
    50%      { box-shadow: 0 0 20px var(--sl-border-col), inset 0 0 10px var(--sl-border-col); }
}
[data-border-style="neon_pulse"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    animation: sl-np-pulse var(--sl-border-dur) ease-in-out infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

@keyframes sl-dg-pulse {
    0%, 100% { filter: drop-shadow(0 0 2px var(--sl-border-col)); }
    50%      { filter: drop-shadow(0 0 12px var(--sl-border-col)) drop-shadow(0 0 24px var(--sl-border-col)); }
}
[data-border-style="dashed_glow"]::after {
    border: var(--sl-border-w) dashed var(--sl-border-col);
    animation: sl-dg-pulse var(--sl-border-dur) ease-in-out infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

@keyframes sl-fd-anim {
    0%, 100% { opacity: 1; }
    50%      { opacity: 0.15; }
}
[data-border-style="fade"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    animation: sl-fd-anim var(--sl-border-dur) ease-in-out infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

@keyframes sl-hb-anim {
    0%, 100% { filter: drop-shadow(0 0 0 var(--sl-border-col)); }
    6%       { filter: drop-shadow(0 0 calc(var(--sl-border-w) * 6) var(--sl-border-col)); }
    12%      { filter: drop-shadow(0 0 0 var(--sl-border-col)); }
    22%      { filter: drop-shadow(0 0 calc(var(--sl-border-w) * 4) var(--sl-border-col)); }
    28%      { filter: drop-shadow(0 0 0 var(--sl-border-col)); }
}
[data-border-style="heartbeat"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    border-radius: inherit;
    animation: sl-hb-anim var(--sl-border-dur) ease-in-out infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

[data-border-style="segments"]::after {
    border: var(--sl-border-w) dashed;
    border-color: var(--sl-border-col) var(--sl-border-col-b);
}

@keyframes sl-ma-scroll {
    from { background-position: 0 0, 0 100%, 0 0, 100% 0; }
    to   { background-position: 12px 0, -12px 100%, 0 -12px, 100% 12px; }
}
[data-border-style="marching_ants"]::after {
    border: none;
    padding: var(--sl-border-w);
    background-image:
        linear-gradient(90deg, var(--sl-border-col) 50%, transparent 50%),
        linear-gradient(90deg, var(--sl-border-col) 50%, transparent 50%),
        linear-gradient(0deg,  var(--sl-border-col) 50%, transparent 50%),
        linear-gradient(0deg,  var(--sl-border-col) 50%, transparent 50%);
    background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
    background-size:
        12px var(--sl-border-w), 12px var(--sl-border-w),
        var(--sl-border-w) 12px, var(--sl-border-w) 12px;
    background-position: 0 0, 0 100%, 0 0, 100% 0;
    animation: sl-ma-scroll var(--sl-border-dur) linear infinite;
    animation-delay: var(--sl-delay-border, 0s);
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
}

@keyframes sl-hz-flow {
    from { background-position: 0 0, 0 100%, 0 0, 100% 0; }
    to   { background-position: 16px 0, -16px 100%, 0 -16px, 100% 16px; }
}
[data-border-style="hazard"]::after {
    border: none;
    padding: var(--sl-border-w);
    background-image:
        repeating-linear-gradient(90deg, var(--sl-border-col) 0 8px, var(--sl-border-col-b) 8px 16px),
        repeating-linear-gradient(90deg, var(--sl-border-col) 0 8px, var(--sl-border-col-b) 8px 16px),
        repeating-linear-gradient(0deg,  var(--sl-border-col) 0 8px, var(--sl-border-col-b) 8px 16px),
        repeating-linear-gradient(0deg,  var(--sl-border-col) 0 8px, var(--sl-border-col-b) 8px 16px);
    background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
    background-size:
        16px var(--sl-border-w), 16px var(--sl-border-w),
        var(--sl-border-w) 16px, var(--sl-border-w) 16px;
    background-position: 0 0, 0 100%, 0 0, 100% 0;
    animation: sl-hz-flow var(--sl-border-dur) linear infinite;
    animation-delay: var(--sl-delay-border, 0s);
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
}

@keyframes sl-rb-hue {
    from { filter: hue-rotate(0deg); }
    to   { filter: hue-rotate(360deg); }
}
[data-border-style="rainbow"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    animation: sl-rb-hue var(--sl-border-dur) linear infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

@property --sl-angle { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
@keyframes sl-cm-rot {
    from { --sl-angle: 0deg; }
    to   { --sl-angle: 360deg; }
}
[data-border-style="comet"]::after {
    border: none;
    background: conic-gradient(
        from var(--sl-angle),
        var(--sl-border-col) 0deg,
        var(--sl-border-col) 30deg,
        var(--sl-border-col-b) 90deg,
        transparent 160deg,
        transparent 360deg
    );
    mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    padding: var(--sl-border-w);
    animation: sl-cm-rot var(--sl-border-dur) linear infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

@keyframes sl-gb-shake {
    0%, 90%, 100% { transform: translate(0, 0); }
    92%           { transform: translate(-2px, 1px); }
    94%           { transform: translate(0, 0); }
    96%           { transform: translate(2px, -1px); }
}
@keyframes sl-gb-color {
    0%, 90%, 100% { border-color: var(--sl-border-col); }
    92%           { border-color: var(--sl-border-col-b); }
    94%           { border-color: var(--sl-border-col); }
    96%           { border-color: var(--sl-border-col-b); }
}
[data-border-style="glitch_border"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    animation:
        sl-gb-shake var(--sl-border-dur) steps(1, end) infinite,
        sl-gb-color var(--sl-border-dur) steps(1, end) infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

@keyframes sl-gdb-slide {
    from { background-position: 0% 50%; }
    to   { background-position: 200% 50%; }
}
[data-border-style="gradient_border"]::after {
    border: none;
    padding: var(--sl-border-w);
    background: linear-gradient(
        90deg,
        var(--sl-border-col),
        var(--sl-border-col-b),
        var(--sl-border-col),
        var(--sl-border-col-b),
        var(--sl-border-col)
    );
    background-size: 200% auto;
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: sl-gdb-slide var(--sl-border-dur) linear infinite;
    animation-delay: var(--sl-delay-border, 0s);
}

[data-border-style="notched"]::after {
    border: var(--sl-border-w) solid var(--sl-border-col);
    clip-path: polygon(
        0 8px, 8px 8px, 8px 0,
        calc(100% - 8px) 0, calc(100% - 8px) 8px, 100% 8px,
        100% calc(100% - 8px), calc(100% - 8px) calc(100% - 8px), calc(100% - 8px) 100%,
        8px 100%, 8px calc(100% - 8px), 0 calc(100% - 8px)
    );
}
